import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.DaUU7NnF.js";const k=JSON.parse('{"title":"JIRA Integration","description":"Connect Matrix rooms to JIRA projects for issue and version notifications","frontmatter":{"title":"JIRA Integration","description":"Connect Matrix rooms to JIRA projects for issue and version notifications","audience":["user","operator","developer"],"integration":"jira","status":"current"},"headers":[],"relativePath":"integrations/jira.md","filePath":"integrations/jira.md","lastUpdated":1775244648000}'),r={name:"integrations/jira.md"};function o(n,t,d,h,l,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="jira" tabindex="-1">JIRA <a class="header-anchor" href="#jira" aria-label="Permalink to &quot;JIRA&quot;">​</a></h1><p>Hookshot connects Matrix rooms to JIRA projects. It delivers notifications for issue creation, updates, and version events. It accepts commands to create and assign issues.</p><p>Supports both <strong>JIRA Cloud</strong> (Atlassian-hosted) and <strong>JIRA Server/Data Center</strong> (self-hosted) with different auth flows.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Supported</th></tr></thead><tbody><tr><td>Receive events in Matrix</td><td>Yes — issue created, updated; version created/updated/released</td></tr><tr><td>Send commands from Matrix</td><td>Yes — 3 commands</td></tr><tr><td>OAuth</td><td>Cloud: OAuth 2.0 / Server: OAuth 1.0 (RSA-SHA1)</td></tr><tr><td>Webhook-based</td><td>Yes</td></tr><tr><td>Bot commands</td><td><code>!jira</code> prefix</td></tr><tr><td>Widget UI</td><td>Yes</td></tr><tr><td>Provisioning API</td><td>Yes</td></tr></tbody></table><h2 id="supported-events" tabindex="-1">Supported events <a class="header-anchor" href="#supported-events" aria-label="Permalink to &quot;Supported events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>JIRA event</th><th>Handler</th><th>Topic</th><th>Filterable</th></tr></thead><tbody><tr><td>Issue created</td><td><code>onJiraIssueCreated</code></td><td><code>jira.issue_created</code></td><td>Yes (default: enabled)</td></tr><tr><td>Issue updated</td><td><code>onJiraIssueUpdated</code></td><td><code>jira.issue_updated</code></td><td>Yes</td></tr><tr><td>Version created</td><td><code>onJiraVersionEvent</code></td><td><code>jira.version_created</code></td><td>Yes</td></tr><tr><td>Version updated</td><td><code>onJiraVersionEvent</code></td><td><code>jira.version_updated</code></td><td>Yes</td></tr><tr><td>Version released</td><td><code>onJiraVersionEvent</code></td><td><code>jira.version_released</code></td><td>Yes</td></tr></tbody></table><p>Events can be filtered per-connection via the <code>events</code> array in the connection state.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><h3 id="jira-cloud-oauth-2-0" tabindex="-1">JIRA Cloud (OAuth 2.0) <a class="header-anchor" href="#jira-cloud-oauth-2-0" aria-label="Permalink to &quot;JIRA Cloud (OAuth 2.0)&quot;">​</a></h3><ol><li>Create an OAuth 2.0 (3LO) app at <a href="https://developer.atlassian.com/console/myapps/create-3lo-app/" target="_blank" rel="noreferrer">developer.atlassian.com</a></li><li>Enable permissions: User REST, Jira Platform REST, User Identity APIs</li><li>Enable rotating tokens under Authorization</li><li>Set callback URL to <code>https://&lt;hookshot&gt;/jira/oauth</code></li><li>Copy Client ID and Secret</li></ol><p>Config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jira</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webhook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-webhook-secret&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oauth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-client-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client_secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-client-secret&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    redirect_uri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hookshot.example.com/jira/oauth&quot;</span></span></code></pre></div><p>The <code>redirect_uri</code> must exactly match the callback URL in Atlassian&#39;s settings.</p><p>User login: <code>!hookshot jira login</code> → opens OAuth flow in browser.</p><h3 id="jira-server-data-center-oauth-1-0" tabindex="-1">JIRA Server / Data Center (OAuth 1.0) <a class="header-anchor" href="#jira-server-data-center-oauth-1-0" aria-label="Permalink to &quot;JIRA Server / Data Center (OAuth 1.0)&quot;">​</a></h3><p>Requires RSA key pair for OAuth 1.0 with RSA-SHA1 signing.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genrsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jira_privatekey.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jira_privatekey.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jira_publickey.pem</span></span></code></pre></div><p>Config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jira</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://jira.internal.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Required for on-premise</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webhook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-webhook-secret&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oauth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    consumerKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-consumer-key&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    privateKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jira_privatekey.pem</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    redirect_uri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hookshot.example.com/jira/oauth&quot;</span></span></code></pre></div><p>Then configure an Application Link in JIRA:</p><ol><li>Administration → Applications → Application Links</li><li>Enter any URL, click Continue</li><li>Set Application Name, Type: Generic Application, enable &quot;Create incoming link&quot;</li><li>Enter your <code>consumerKey</code>, any consumer name, and the public key from <code>jira_publickey.pem</code></li></ol><h2 id="webhook-setup" tabindex="-1">Webhook setup <a class="header-anchor" href="#webhook-setup" aria-label="Permalink to &quot;Webhook setup&quot;">​</a></h2><h3 id="cloud" tabindex="-1">Cloud <a class="header-anchor" href="#cloud" aria-label="Permalink to &quot;Cloud&quot;">​</a></h3><p>See <a href="https://support.atlassian.com/jira-cloud-administration/docs/manage-webhooks/" target="_blank" rel="noreferrer">Atlassian webhook docs</a>. Set the webhook secret to match your config.</p><h3 id="server-data-center" tabindex="-1">Server / Data Center <a class="header-anchor" href="#server-data-center" aria-label="Permalink to &quot;Server / Data Center&quot;">​</a></h3><p>Settings → System → WebHooks. Point to <code>https://&lt;hookshot&gt;/jira/webhook?secret=your-webhook-secret</code>.</p><p>Enable issue and version events.</p><h2 id="bot-commands" tabindex="-1">Bot commands <a class="header-anchor" href="#bot-commands" aria-label="Permalink to &quot;Bot commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>!jira create &lt;title&gt;</code></td><td>Create an issue</td><td><code>!jira create &quot;Login bug&quot;</code></td></tr><tr><td><code>!jira issue-types</code></td><td>List issue types for the project</td><td><code>!jira issue-types</code></td></tr><tr><td><code>!jira assign &lt;number&gt; &lt;user&gt;</code></td><td>Assign an issue</td><td><code>!jira assign PROJ-42 jane</code></td></tr></tbody></table><p>Admin commands (DM with bot):</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>!hookshot jira login</code></td><td>Start OAuth flow</td></tr><tr><td><code>!hookshot jira logout</code></td><td>Clear stored credentials</td></tr><tr><td><code>!hookshot jira whoami</code></td><td>Check JIRA identity</td></tr></tbody></table><h2 id="setup-connect-a-room" tabindex="-1">Setup: Connect a room <a class="header-anchor" href="#setup-connect-a-room" aria-label="Permalink to &quot;Setup: Connect a room&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot jira project https://jira.example.com/projects/PROJ</span></span></code></pre></div><p>Or use the widget UI.</p><h2 id="webhook-verification" tabindex="-1">Webhook verification <a class="header-anchor" href="#webhook-verification" aria-label="Permalink to &quot;Webhook verification&quot;">​</a></h2><p>JIRA webhooks are verified using two strategies:</p><ol><li><strong>Query parameter secret</strong> — On-premise JIRA appends <code>?secret=...</code> to the webhook URL. Hookshot compares directly.</li><li><strong>HMAC-SHA256 signature</strong> — JIRA Cloud sends <code>x-hub-signature</code> header with <code>sha256=&lt;hex&gt;</code> format.</li></ol><p>Hookshot auto-detects Cloud vs On-Premise by checking for the <code>x-atlassian-webhook-identifier</code> header.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><code>jira-client</code> npm package (v8.2.2) is unmaintained — last meaningful update was years ago</li><li>JIRA Server reached EOL February 2024 — hookshot still supports it but Data Center may behave differently</li><li>OAuth 1.0 with RSA-SHA1 for Server is legacy — Data Center supports OAuth 2.0 but hookshot doesn&#39;t implement it for on-premise</li><li>On-Premise OAuth 1.0a tokens have no refresh capability — users must re-authenticate when tokens expire</li><li>Only issue and version events are supported — no board, sprint, or comment events</li><li>Cloud OAuth tokens auto-refresh; accessible resources cached with 60s TTL</li><li>The split between Cloud and Server clients adds maintenance burden</li></ul><h2 id="upstream-references" tabindex="-1">Upstream references <a class="header-anchor" href="#upstream-references" aria-label="Permalink to &quot;Upstream references&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>URL</th></tr></thead><tbody><tr><td>JIRA Cloud REST API</td><td><a href="https://developer.atlassian.com/cloud/jira/platform/rest/v3/" target="_blank" rel="noreferrer">developer.atlassian.com</a></td></tr><tr><td>JIRA Cloud webhooks</td><td><a href="https://support.atlassian.com/jira-cloud-administration/docs/manage-webhooks/" target="_blank" rel="noreferrer">Atlassian webhook docs</a></td></tr><tr><td>OAuth 2.0 (3LO)</td><td><a href="https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/" target="_blank" rel="noreferrer">Atlassian OAuth docs</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/integration-model">Integration Model</a> · <a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></p><p><strong>Integrations:</strong> <a href="./overview">Overview</a> · <a href="./github">GitHub</a> · <a href="./gitlab">GitLab</a> · <a href="./openproject">OpenProject</a> — Similar project tracking</p><p><strong>Reference:</strong> <a href="./../reference/bot-commands#jira-project-commands">Bot Commands: JIRA</a> · <a href="./../reference/event-types">Event Types</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/configuration">Configuration</a> · <a href="./../guides/operator/hardening">Hardening</a></p><p><strong>Troubleshooting:</strong> <a href="./../troubleshooting/authentication">Authentication</a> · <a href="./../troubleshooting/webhooks-not-arriving">Webhooks Not Arriving</a> · <a href="./../troubleshooting/common-errors">Common Errors</a></p>`,49)])])}const u=e(r,[["render",o]]);export{k as __pageData,u as default};
